"use client";

import { loadVariableFont } from "@remotion/google-fonts/InterTight";
import { type ReactNode, useEffect, useMemo, useRef, useState } from "react";
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  Easing,
  interpolate,
  spring,
} from "remotion";
import { useSceneConfig, useSceneFrame } from "@/lib/remocn/frame-rate";
import { useGlide } from "@/lib/remocn/glide";
import { type Timing, useTimeline } from "@/lib/remocn/timeline";
import { type BeatCountElementId, beatCountTimeline } from "./timeline";

const inter = loadVariableFont("normal", { subsets: ["latin"] });

export interface BeatCountProps {
  value?: number;
  from?: number;
  beats?: number;
  bpm?: number;
  decimals?: number;
  prefix?: string;
  suffix?: string;
  label?: string;
  accent?: string;
  /** Text color of the number; overrides the theme ink. */
  ink?: string;
  background?: string;
  /** Typeface for the number and caption. Load it yourself; Inter Tight by default. */
  fontFamily?: string;
  /** Weight of the number between beats; each beat swells it toward 500. */
  fontWeight?: number;
  /** How far each beat squashes the number, as a fraction of its height. */
  punch?: number;
  /** Size of the number and caption, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  speed?: number;
  theme?: "dark" | "light";
  /**
   * Moves, trims or stretches the entry, single beats and the caption, by
   * the ids in `./timeline`. Frames on the scene timeline, after `delay` and
   * `speed`.
   */
  timing?: Timing<BeatCountElementId>;
}

const THEMES = {
  dark: {
    bg: "#1C1C1E",
    ink: "#E9E9E6",
    accent: "#6D5BFF",
  },
  light: {
    bg: "#E9E9E6",
    ink: "#0B0B0C",
    accent: "#6D5BFF",
  },
} as const;

const WGHT = { rest: 200, duck: 500 } as const;
const TRACK = { rest: -0.045, duck: -0.01 } as const;
const DUCK = 0.2;
const LAST_DUCK = 0.3;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

function format(v: number, decimals: number) {
  return v.toLocaleString("en-US", {
    minimumFractionDigits: decimals,
    maximumFractionDigits: decimals,
  });
}

interface Metrics {
  rest: number;
  duck: number;
  figTop: number;
  baseline: number;
}

function measure(text: string, fontFamily: string, weight: number): Metrics {
  const ctx = document.createElement("canvas").getContext("2d");
  let rest = 0.55 * text.length;
  let duck = 0.62 * text.length;
  let figTop = 0.72;
  let baseline = 0.8;
  if (ctx) {
    ctx.font = `${weight} 200px "${fontFamily}"`;
    ctx.letterSpacing = `${TRACK.rest * 200}px`;
    rest = ctx.measureText(text).width / 200;
    ctx.font = `${WGHT.duck} 200px "${fontFamily}"`;
    ctx.letterSpacing = `${TRACK.duck * 200}px`;
    duck = ctx.measureText(text).width / 200;
    const fm = ctx.measureText("0");
    const asc = fm.fontBoundingBoxAscent / 200;
    const desc = fm.fontBoundingBoxDescent / 200;
    baseline = (1 - (asc + desc)) / 2 + asc;
    figTop = fm.actualBoundingBoxAscent / 200;
  }
  return { rest, duck, figTop, baseline };
}

function useMetrics(text: string, fontFamily: string, rest: number) {
  const key = `${rest} ${fontFamily} ${text}`;
  const [state, setState] = useState<{ key: string; m: Metrics } | null>(null);
  const [handle] = useState(() => delayRender("beat-count: measuring"));
  const released = useRef(false);
  useEffect(() => {
    let live = true;
    Promise.all([
      inter.waitUntilDone(),
      document.fonts.load(`${rest} 100px "${fontFamily}"`),
      document.fonts.load(`${WGHT.duck} 100px "${fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        setState({ key, m: measure(text, fontFamily, rest) });
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [key, text, fontFamily, rest, handle]);
  return state && state.key === key ? state.m : null;
}

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

const midway = (p: number) => p > 5e-4 && p < 1 - 5e-4;

function envelope(since: number, release: number) {
  if (since < 0) return 0;
  const attack = Math.min(1, (since + 1) / 2);
  return attack * Math.exp(-Math.max(0, since - 1) / release);
}

export function BeatCount(props: BeatCountProps) {
  const {
    value = 64,
    from = 0,
    decimals = 0,
    prefix = "",
    suffix = "",
    label = "cuts, each one landing on the kick",
    accent,
    ink,
    background,
    fontFamily = inter.fontFamily,
    fontWeight = WGHT.rest,
    punch = DUCK,
    scale = 1,
    delay = 0,
    speed = 1,
    theme = "dark",
    timing,
  } = props;
  const glide = useGlide();
  const t = Math.max(0, useSceneFrame() - delay) * speed;
  const { width: W, height: H, fps, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    beatCountTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const c = THEMES[theme];
  const spot = accent ?? c.accent;
  const fg = ink ?? c.ink;
  const finalText = useMemo(
    () => `${prefix}${format(value, decimals)}${suffix}`,
    [prefix, value, decimals, suffix],
  );
  const m = useMetrics(finalText, fontFamily, fontWeight);

  const transparent = background === "transparent";
  const stage = transparent ? "transparent" : (background ?? c.bg);

  if (!m) {
    return (
      <div style={{ position: "absolute", inset: 0, background: stage }} />
    );
  }

  const portrait = H > W * 1.1;
  const s = portrait ? W / 1080 : Math.min(W / 1280, H / 720);

  const beatEls = tl.lane("Beats");
  const n = beatEls.length;
  const lastBeat = beatEls[n - 1].start;
  // The beat playing at `f`: the last one started, -1 before the first.
  const beatOf = (f: number) => {
    let b = -1;
    for (let i = 0; i < n; i++) if (f >= beatEls[i].start) b = i;
    return b;
  };
  const k = beatOf(t);

  const shown = k < 0 ? from : from + ((value - from) * (k + 1)) / n;
  const text = `${prefix}${format(
    Math.round(shown * 10 ** decimals) / 10 ** decimals,
    decimals,
  )}${suffix}`;

  const duckAt = (f: number) => {
    const b = beatOf(f);
    if (b === n - 1) {
      const since = f - lastBeat;
      const back = spring({
        frame: since - 2,
        fps,
        config: { damping: 9, stiffness: 120, mass: 0.8 },
      });
      const attack = Math.min(1, (since + 1) / 2);
      return LAST_DUCK * (since < 2 ? attack : 1 - back);
    }
    return b < 0
      ? 0
      : envelope(f - beatEls[b].start, beatEls[b].beat("release")) * punch;
  };
  const d = duckAt(t);
  // The squash decays and springs without a clean end, so the test is on
  // the squash itself, against the neighbouring frames.
  const squashing =
    Math.abs(duckAt(t + speed) - d) > 2e-6 ||
    Math.abs(d - duckAt(t - speed)) > 2e-6;
  const duck = Math.max(0, Math.min(1, d / LAST_DUCK));
  const sy = 1 - d;
  const wght = fontWeight + (WGHT.duck - fontWeight) * duck;
  const track = TRACK.rest + (TRACK.duck - TRACK.rest) * duck;

  const margin = portrait ? W * 0.08 : W * 0.065;
  const F = Math.min(
    (W * (portrait ? 0.84 : 0.66)) / Math.max(0.1, m.duck),
    (H * (portrait ? 0.3 : 0.66)) / Math.max(0.1, m.figTop),
  );
  const baseY = H - margin;
  const boxTop = baseY - m.baseline * F;
  const labelFs = (portrait ? 50 : 32) * s;

  const enterEl = tl.get("enter");
  const labelEl = tl.get("label");
  const enterAt = (f: number) =>
    interpolate(f, [enterEl.start, enterEl.end], [0, 1], {
      ...CLAMP,
      easing: EASE_OUT,
    });
  const enter = enterAt(t);
  // The rise lands a frame before the first beat squashes the figure, so the
  // tilt holds through the landing frame instead of blinking off for it.
  const entering = enter !== enterAt(t - speed) || enter !== enterAt(t + speed);
  const labelP = interpolate(t, [labelEl.start, labelEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      <ScaleLayer scale={scale}>
        <div
          style={{
            position: "absolute",
            right: margin - F * 0.02,
            top: boxTop,
            height: F,
            lineHeight: `${F}px`,
            whiteSpace: "pre",
            fontFamily,
            fontSize: F,
            fontVariationSettings: `"wght" ${wght.toFixed(1)}`,
            fontVariantNumeric: "tabular-nums",
            letterSpacing: `${track.toFixed(4)}em`,
            color: fg,
            opacity: enter,
            transformOrigin: `100% ${(m.baseline * F).toFixed(1)}px`,
            transform: `translateY(${((1 - enter) * F * 0.08).toFixed(2)}px) scaleY(${sy.toFixed(4)})${glide(squashing || entering)}`,
          }}
        >
          {text}
        </div>

        {label ? (
          <div
            style={{
              position: "absolute",
              left: margin,
              top: margin,
              width: W * (portrait ? 0.7 : 0.34),
              fontFamily,
              fontVariationSettings: `"wght" 400`,
              fontSize: labelFs,
              lineHeight: 1.2,
              letterSpacing: "-0.015em",
              textWrap: "balance",
              color: spot,
              opacity: labelP,
              transform: `translateY(${((1 - labelP) * labelFs * 0.5).toFixed(2)}px)${glide(midway(labelP))}`,
            }}
          >
            {label}
          </div>
        ) : null}
      </ScaleLayer>
    </AbsoluteFill>
  );
}

import { defineTimeline, type TimelineElement } from "@/lib/remocn/timeline";

// The number rising in, then one element per beat of the count: each beat
// steps the number and squashes it on the kick. The caption lands after the
// first beat. Frames on the 30 fps scene timeline, after `delay` and
// `speed`. The ids are public: a saved `timing` prop refers to them.

export type BeatCountElementId = "enter" | `beat:${number}` | "label";

export interface BeatCountTimingProps {
  beats?: number;
  bpm?: number;
}

/** Frames per second of the scene timeline the schedule counts in. */
const FPS = 30;
const FIRST_BEAT = 12;
const ENTER_LEN = 10;

// `enter` is the number rising in. `beat:<k>` is beat `k` of the count, one
// beat long: the number steps and squashes, decaying over `release`. The
// beats chain. `label` is the caption, following the first beat.
export const beatCountTimeline = defineTimeline<
  BeatCountElementId,
  BeatCountTimingProps
>(({ beats = 8, bpm = 120 }) => {
  const n = Math.max(1, Math.round(beats));
  const beatLen = (FPS * 60) / Math.max(30, bpm);
  const release = Math.max(2, beatLen * 0.26);
  const out: TimelineElement<BeatCountElementId>[] = [
    {
      id: "enter",
      lane: "Number",
      label: "enter",
      start: 0,
      length: ENTER_LEN,
    },
  ];
  for (let b = 0; b < n; b++) {
    out.push({
      id: `beat:${b}`,
      lane: "Beats",
      label: `beat ${b + 1}`,
      start: FIRST_BEAT + b * beatLen,
      length: beatLen,
      follows: b > 0 ? `beat:${b - 1}` : undefined,
      beats: { release },
    });
  }
  out.push({
    id: "label",
    lane: "Caption",
    label: "caption",
    start: FIRST_BEAT + beatLen,
    length: 16,
    follows: "beat:0",
  });
  return out.sort((a, b) => a.start - b.start);
});
